<?php
require_once __DIR__ . '/../config/config.php';require_once __DIR__ . '/../includes/session.php';require_once __DIR__ . '/../includes/auth.php';require_login();require_module_access($conn,'maternity','view');
$total=(int)($conn->query("SELECT COUNT(*) c FROM maternity")->fetch_assoc()['c']??0);$deliveries=(int)($conn->query("SELECT COUNT(*) c FROM maternity_delivery")->fetch_assoc()['c']??0);$babies=(int)($conn->query("SELECT COUNT(*) c FROM maternity_baby")->fetch_assoc()['c']??0);
$monthly=$conn->query("SELECT DATE_FORMAT(created_at,'%Y-%m') ym,COUNT(*) c FROM maternity_delivery GROUP BY ym ORDER BY ym DESC LIMIT 12");$recent=$conn->query("SELECT d.*,p.full_name,m.anc_number FROM maternity_delivery d JOIN maternity m ON m.id=d.maternity_id JOIN patients p ON p.id=m.patient_id ORDER BY d.created_at DESC LIMIT 20");
include __DIR__ . '/../includes/header.php';include __DIR__ . '/../includes/sidebar.php';?>
<div class="main-content"><div class="container-fluid pt-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="h4 mb-1 text-gray-800"><i class="fas fa-chart-bar text-primary mr-2"></i>Maternity Reports</h2><p class="text-muted mb-0">Operational maternity and delivery statistics.</p></div><a href="index.php" class="btn btn-light">Maternity Dashboard</a></div><div class="row mb-4"><div class="col-md-4"><div class="card shadow-sm"><div class="card-body"><small class="text-muted">Maternity Records</small><div class="h4 mb-0"><?=$total?></div></div></div></div><div class="col-md-4"><div class="card shadow-sm"><div class="card-body"><small class="text-muted">Deliveries</small><div class="h4 mb-0"><?=$deliveries?></div></div></div></div><div class="col-md-4"><div class="card shadow-sm"><div class="card-body"><small class="text-muted">Newborn Records</small><div class="h4 mb-0"><?=$babies?></div></div></div></div></div><div class="row"><div class="col-lg-5 mb-4"><div class="card shadow-sm"><div class="card-header bg-white"><strong>Monthly Deliveries</strong></div><div class="card-body"><table class="table table-sm"><thead><tr><th>Month</th><th>Deliveries</th></tr></thead><tbody><?php if($monthly&&$monthly->num_rows):while($r=$monthly->fetch_assoc()):?><tr><td><?=htmlspecialchars($r['ym'])?></td><td><?=htmlspecialchars($r['c'])?></td></tr><?php endwhile;else:?><tr><td colspan="2" class="text-muted text-center">No delivery data.</td></tr><?php endif;?></tbody></table><a class="btn btn-sm btn-outline-primary" href="stats_export_csv.php">Export CSV</a></div></div></div><div class="col-lg-7 mb-4"><div class="card shadow-sm"><div class="card-header bg-white"><strong>Recent Deliveries</strong></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Date</th><th>Patient</th><th>Mode</th><th>Baby Weight</th></tr></thead><tbody><?php if($recent&&$recent->num_rows):while($r=$recent->fetch_assoc()):?><tr><td><?=htmlspecialchars(date('d M Y H:i',strtotime($r['delivery_time']??$r['created_at'])))?></td><td><?=htmlspecialchars($r['full_name'])?><br><small><?=htmlspecialchars($r['anc_number'])?></small></td><td><?=htmlspecialchars($r['delivery_mode'])?></td><td><?=htmlspecialchars($r['baby_weight']??'—')?></td></tr><?php endwhile;else:?><tr><td colspan="4" class="text-center text-muted py-4">No delivery records.</td></tr><?php endif;?></tbody></table></div></div></div></div></div></div><?php include __DIR__ . '/../includes/footer.php'; ?>